-- 👀 Methods for handling third eye (or target) interactions
-- Returns a unique option name for ox_target so multiple options with the same event (e.g. useEmote) don't collide.
local function SHX3_1(SHX4_1)
    local SHX5_1 = string.split(properties.event, ":")[2]
    if not SHX5_1 then return "option" end
    if properties.name then return properties.name end
    if properties.label and properties.label ~= "" then
        local SHX6_1 = string.gsub(string.gsub(string.lower(properties.label), "%s+", "_"), "[^%w_]", "")
        if SHX6_1 ~= "" then return SHX5_1 .. "_" .. SHX6_1 end
    end
    return SHX5_1
end

---@param properties table
---@param checkDistance boolean?
local function SHX7_1(SHX4_1, SHX8_1)
    return function(SHX9_1, SHX10_1)
        if not SafeEntity.isValid(SHX9_1) then
            return false
        end

        if SHX8_1 and properties.distance and SHX10_1 > properties.distance then
            return false
        end

        if not properties.canInteractCallback then
            if SHX8_1 and properties.distance then
                return SHX10_1 <= properties.distance
            end
            return true
        end

        return SafeEntity.runCanInteract(properties.canInteractCallback, SHX9_1)
            and (not SHX8_1 or not properties.distance or SHX10_1 <= properties.distance)
    end
end

