function SHX1_1(SHX2_1, SHX3_1, SHX4_1)
	SHX4_1 = SHX4_1 or {}
	local SHX5_1 = {
		{unselectable = true, icon = "fas fa-user", title = TranslateCap('boss_menu')}
	}

	ESX.TriggerServerCallback('esx_society:isBoss', function(SHX6_1)
		if SHX6_1 then
			local SHX7_1 = {
				checkBal = true,
				withdraw = true,
				deposit = true,
				wash = true,
				SHX8_1 = true,
				salary = true,
				grades = true
			}

			for SHX9_1,SHX10_1 in pairs(SHX7_1) do
				if SHX4_1[SHX9_1] == nil then
					SHX4_1[SHX9_1] = SHX10_1
				end
			end

			if options.checkBal then
				SHX5_1[#SHX5_1+1] = {icon = "fas fa-wallet", title = TranslateCap('check_society_balance'), value = "check_society_balance"}
			end
