				SHX5_1[#SHX5_1+1] = {icon = "fas fa-wallet", title = TranslateCap('withdraw_society_money'), value = "withdraw_society_money"}
			end
			if options.deposit then
				SHX5_1[#SHX5_1+1] = {icon = "fas fa-wallet", title = TranslateCap('deposit_society_money'), value = "deposit_money"}
			end
			if options.wash then
				SHX5_1[#SHX5_1+1] = {icon = "fas fa-wallet", title = TranslateCap('wash_money'), value = "wash_money"}
			end
			if options.employees then
				SHX5_1[#SHX5_1+1] = {icon = "fas fa-users", title = TranslateCap('employee_management'), value = "manage_employees"}
