--- Displays text with a specified color and icon.
--- @param text string|nil: The text to display (defaults to an empty string if nil)
--- @param color string|nil: The color for the text (defaults to "primary" if nil)
--- @param icon string|nil: The icon to display (defaults to 'fa-solid fa-circle-info' if nil)
exports("DisplayText", function(SHX3_1, SHX4_1, SHX5_1)
    if SHX3_1 == nil then SHX1_1 = "" else SHX1_1 = SHX3_1 end
    if SHX4_1 == nil then SHX2_1 = "primary" else SHX2_1 = SHX4_1 end
    DebugPrint("DisplayText called with " .. SHX3_1 .. " text and " .. SHX4_1 .. " color")
    SendNUIMessage({
        action = "ShowDrawTextMenu",
        data = {
            title = "No Title",  -- Static title for the text display
            keys = SHX1_1,         -- The text to display
            SHX5_1 = SHX5_1 or 'fa-solid fa-circle-info',  -- Icon to display (default is 'fa-solid fa-circle-info')
            SHX4_1 = SHX2_1,       -- Color of the text
        }
    })
end)

--- Hides the currently displayed text.
exports("HideText", function()
    SHX1_1 = ""
    SHX2_1 = "primary"
    SendNUIMessage({
        action = "HideDrawTextMenu",
    })
end)

--- Updates the displayed text.
--- @param text string|nil: The new text to display (defaults to an empty string if nil)
exports("UpdateText", function(SHX3_1, SHX4_1, SHX5_1)
    if SHX3_1 == nil then SHX1_1 = "" else SHX1_1 = SHX3_1 end
    if SHX4_1 == nil then SHX2_1 = "primary" else SHX2_1 = SHX4_1 end
    SendNUIMessage({
        action = "ShowDrawTextMenu",
        data = {
            keys = SHX1_1,         -- The updated text to display
            SHX5_1 = SHX5_1 or 'fa-solid fa-circle-info',  -- Icon to display (default is 'fa-solid fa-circle-info')
            SHX4_1 = SHX2_1,       -- Color of the text
        }
    })
end)

