    local SHX6_1 = self:SHX2_1()
    local SHX1_1 = self.prefix[SHX5_1] or self.prefix['info']
    return print(('%s %s^3 >>> ^7%s'):format(SHX6_1, SHX1_1, SHX4_1))
end

